/** The command line: add, list, done, and rm. */

import { ArgError, lastValue, parseArgs } from "./args.ts";
import type { ArgSpec } from "./args.ts";
import { todayUtc } from "./dates.ts";
import { formatList } from "./format.ts";
import { loadStore, saveStore, StoreError } from "./store.ts";
import { addTodo, completeTodo, removeTodo, TodoError } from "./todos.ts";
import type { Io } from "./types.ts";

const DEFAULT_FILE = "todos.json";

const SPEC: ArgSpec = { values: ["file", "due"], flags: ["open"] };

const USAGE = `usage: todo [--file FILE] COMMAND

commands:
  add TITLE [--due YYYY-MM-DD]   add an item
  list [--open]                  show the list (--open hides finished items)
  done NUMBER                    mark an item done
  rm NUMBER                      remove an item
  help                           show this text
`;

function numberArg(command: string, text: string | undefined): number {
  if (text === undefined) {
    throw new ArgError(`${command} needs a todo number`);
  }
  if (!/^\d+$/.test(text)) {
    throw new ArgError(`"${text}" is not a todo number`);
  }
  return Number(text);
}

function run(argv: readonly string[], io: Io): number {
  const parsed = parseArgs(argv, SPEC);
  const [command, ...rest] = parsed.positional;
  if (command === undefined || command === "help") {
    (command === undefined ? io.err : io.out)(USAGE);
    return command === undefined ? 2 : 0;
  }
  const path = lastValue(parsed, "file") ?? DEFAULT_FILE;
  const today = io.today?.() ?? todayUtc();

  if (command === "add") {
    if (rest.length === 0) {
      throw new ArgError("add needs a title");
    }
    const file = loadStore(path);
    const todo = addTodo(file, rest.join(" "), { due: lastValue(parsed, "due") ?? null }, today);
    saveStore(path, file);
    io.out(`Added #${todo.id}: ${todo.title}\n`);
    return 0;
  }
  if (command === "list") {
    const file = loadStore(path);
    let todos = file.todos;
    if (parsed.flags.has("open")) {
      todos = todos.filter((todo) => !todo.done);
    }
    io.out(formatList(todos));
    return 0;
  }
  if (command === "done" || command === "rm") {
    const id = numberArg(command, rest[0]);
    const file = loadStore(path);
    if (command === "done") {
      completeTodo(file, id);
    } else {
      removeTodo(file, id);
    }
    saveStore(path, file);
    io.out(`${command === "done" ? "Completed" : "Removed"} #${id}\n`);
    return 0;
  }
  throw new ArgError(`unknown command "${command}" (try "todo help")`);
}

/** Run the command line and return the exit status: 0, 1 for a missing item or file problem, 2 for bad input. */
export function main(argv: readonly string[], io: Io): number {
  try {
    return run(argv, io);
  } catch (error) {
    if (error instanceof ArgError) {
      io.err(`todo: ${error.message}\n`);
      return 2;
    }
    if (error instanceof TodoError) {
      io.err(`todo: ${error.message}\n`);
      return error.code === "invalid" ? 2 : 1;
    }
    if (error instanceof StoreError) {
      io.err(`todo: ${error.message}\n`);
      return 1;
    }
    throw error;
  }
}

/** Operations on the items of a todo file. */

import { isValidDay } from "./dates.ts";
import type { Todo, TodoFile } from "./types.ts";

/** Thrown for a request the list cannot carry out. */
export class TodoError extends Error {
  readonly code: "not-found" | "invalid";

  constructor(code: "not-found" | "invalid", message: string) {
    super(message);
    this.name = "TodoError";
    this.code = code;
  }
}

/** What `addTodo` accepts besides the title. */
export interface AddOptions {
  due?: string | null;
}

/** Add an item at the end of the list and return it. */
export function addTodo(file: TodoFile, title: string, options: AddOptions, today: string): Todo {
  const trimmed = title.trim();
  if (trimmed === "") {
    throw new TodoError("invalid", "a todo needs a title");
  }
  const due = options.due ?? null;
  if (due !== null && !isValidDay(due)) {
    throw new TodoError("invalid", `"${due}" is not a day in the form YYYY-MM-DD`);
  }
  const todo: Todo = { id: file.nextId, title: trimmed, done: false, due, created: today };
  file.todos.push(todo);
  file.nextId += 1;
  return todo;
}

/** The item with this id. */
export function findTodo(file: TodoFile, id: number): Todo {
  const todo = file.todos.find((item) => item.id === id);
  if (todo === undefined) {
    throw new TodoError("not-found", `no todo with number ${id}`);
  }
  return todo;
}

/** Mark an item done and return it. */
export function completeTodo(file: TodoFile, id: number): Todo {
  const todo = findTodo(file, id);
  todo.done = true;
  return todo;
}

/** Take an item off the list and return it. */
export function removeTodo(file: TodoFile, id: number): Todo {
  const todo = findTodo(file, id);
  file.todos = file.todos.filter((item) => item.id !== id);
  return todo;
}

/** A small command-line argument parser: words, flags, and options that take a value. */

/** Thrown for an option that is unknown or that lacks its value. */
export class ArgError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ArgError";
  }
}

/** The options a command line may use, without their leading dashes. */
export interface ArgSpec {
  /** Options that take a value (`--file todos.json` or `--file=todos.json`). */
  values: readonly string[];
  /** Options that stand alone (`--open`). */
  flags: readonly string[];
}

export interface ParsedArgs {
  positional: string[];
  /** Every value given for an option, in order (an option may be repeated). */
  values: Map<string, string[]>;
  flags: Set<string>;
}

/** Split an argument list into words, flags, and option values. */
export function parseArgs(argv: readonly string[], spec: ArgSpec): ParsedArgs {
  const parsed: ParsedArgs = { positional: [], values: new Map(), flags: new Set() };
  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    if (!arg.startsWith("--") || arg === "--") {
      parsed.positional.push(arg);
      continue;
    }
    const equals = arg.indexOf("=");
    const name = equals === -1 ? arg.slice(2) : arg.slice(2, equals);
    if (spec.flags.includes(name) && equals === -1) {
      parsed.flags.add(name);
    } else if (spec.values.includes(name)) {
      let value: string | undefined;
      if (equals === -1) {
        index += 1;
        value = argv[index];
      } else {
        value = arg.slice(equals + 1);
      }
      if (value === undefined) {
        throw new ArgError(`--${name} needs a value`);
      }
      parsed.values.set(name, [...(parsed.values.get(name) ?? []), value]);
    } else {
      throw new ArgError(`unknown option --${name}`);
    }
  }
  return parsed;
}

/** The last value given for an option, or undefined. */
export function lastValue(parsed: ParsedArgs, name: string): string | undefined {
  return parsed.values.get(name)?.at(-1);
}
